body.query:
query productsQuery($first: Int, $after: String, $query: String!) {
  products(query: $query, after: $after, first: $first) {
    edges {
      node {
        id
        _id
        uid
        slug
        title
        description
        notice_text
        price
        sku
        file_id
        compare_at_price
        product_type
        thumbnail {
          id
          path
        }
        file {
          id
          title
          size
          path
        }
        tags {
          id
          title
        }
        variants {
          id
          price
          compare_at_price
          sku
          enable_inventory_limit
          inventory_quantity
        }
        inventory_quantity
        enable_inventory_limit
        created_at
        updated_at
      }
      cursor
    }
    pageInfo {
      endCursor
      hasNextPage
    }
  }
}
